layer.css:
[data-ryt="footer"] { color: var(--ryt-bg); background-color: var(--ryt-text); font-style: normal; letter-spacing: normal; text-transform: none }
[data-ryt="brand"] { color: var(--ryt-accent); border-radius: 0px; font-family: Nunito, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, Roboto, Ubuntu, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"; font-size: 16px; font-weight: 700; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: var(--ryt-text); border-radius: 0px; font-family: Nunito, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, Roboto, Ubuntu, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"; font-size: 16px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 0.8px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 25px; padding-right: 5px; padding-bottom: 25px; padding-left: 0px; transition: color 0.5s }
[data-ryt="button"] { color: var(--ryt-bg); background-color: rgb(1, 101, 84); border-radius: 47px; font-family: Nunito, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, Roboto, Ubuntu, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 0.7px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 10px; padding-right: 20px; padding-bottom: 10px; padding-left: 20px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-accent); border-radius: 0px; font-family: Oswald, Impact, "Arial Black", sans-serif, -apple-system, BlinkMacSystemFont, Roboto, Ubuntu; font-weight: 700; font-style: normal; letter-spacing: normal; text-transform: uppercase; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-accent); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: rgb(90, 161, 0); border-radius: 0px; font-family: Oswald, Impact, "Arial Black", sans-serif, -apple-system, BlinkMacSystemFont, Roboto, Ubuntu; font-size: 34px; font-weight: 700; font-style: normal; line-height: 1.15; letter-spacing: normal; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(90, 161, 0); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #016554 }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #016554 }
[data-ryt="button"]:hover { color: #016554; color: #ffffff; background-color: #003c32 }
[data-ryt="nav"] a::after { content: ""; display: block; width: 10px; height: 6px; margin-left: 10px; color: var(--ryt-text); background-image: url("data:image/svg+xml,%3Csvg width='9' height='6' fill='none' xmlns='http://www.w3.org/2000/svg'%3E%3Cpath d='M1.21 1.078l3.395 3 3.395-3' stroke='%23b1b1b1' stroke-width='2' stroke-linecap='round'/%3E%3C/svg%3E"); background-size: 9px auto; background-position: 0% 0%; background-repeat: no-repeat; border-radius: 0px; font-family: Nunito, -apple-system, BlinkMacSystemFont, "Segoe UI", Helvetica, Arial, sans-serif, Roboto, Ubuntu, "Apple Color Emoji", "Segoe UI Emoji", "Segoe UI Symbol"; font-size: 16px; font-weight: 700; font-style: normal; line-height: 1; letter-spacing: 0.8px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: 0.2s ease-out; -webkit-text-fill-color: var(--ryt-text) }
[data-ryt="nav"] a:hover { color: #016554; color: #5f6367 }
[data-ryt="brand"]:hover { color: #016554 }
